mapper.sql:
sr.status = '정상' AND c.approval_status = '승인' AND c.company_status = '정상'
AND c.company_name LIKE CONCAT('%', #{keyword}, '%')
AND c.company_size = #{companySize}
AND c.industry_name = #{industry}
AND sr.career_years <= 1 AND sr.career_years BETWEEN 1 AND 3 AND sr.career_years BETWEEN 4 AND 7 AND sr.career_years >= 8

mapper.select:
SELECT c.company_id AS companyId, c.company_name AS companyName, c.industry_name AS industryName, c.company_size AS companySize, c.address_line1 AS addressLine1, c.logo_url AS logoUrl, ROUND(AVG(sr.base_salary)) AS averageSalary, ROUND(AVG(CASE WHEN sr.career_years <= 1 THEN sr.base_salary END)) AS newcomerAverageSalary, COUNT(*) AS recordCount, MAX(sr.updated_at) AS latestUpdatedAt FROM salary_records sr JOIN companies c ON c.company_id = sr.company_id WHERE GROUP BY c.company_id, c.company_name, c.industry_name, c.company_size, c.address_line1, c.logo_url
ORDER BY latestUpdatedAt DESC ORDER BY recordCount DESC, averageSalary DESC ORDER BY averageSalary DESC, recordCount DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM job_categories
WHERE job_category_id = #{jobCategoryId}
  AND is_active = TRUE

SELECT COUNT(*) FROM salary_records
WHERE author_user_id = #{userId}
  AND company_id = #{companyId}
  AND salary_year = #{salaryYear}

SELECT COUNT(*) FROM salary_records
WHERE author_user_id = #{userId}
  AND company_id = #{companyId}
  AND salary_year = #{salaryYear}
  AND salary_record_id != #{salaryRecordId}

